window.CARDS=window.CARDS||{};CARDS["people-ichinose-honami"]=[{"i":"sc-ichinose-honami-y1v1-p141-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"hoshinomiya-chie ichinose-honami","q":"debut  student council liaison hallway outside faculty staff room   hoshinomiya sensei  do you have a moment  the student council wishes to discuss something with you","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v1-p141-1\"><h3><span class=\"ttl\">Debut: student council liaison<\/span><span class=\"meta\">Y1V1 · p.141–142<\/span><\/h3><p class=\"setup\">Hallway outside faculty staff room.<\/p><p class=\"with\">with <a href=\"hoshinomiya-chie.html\">Hoshinomiya Chie<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hoshinomiya-sensei, do you have a moment? The student council wishes to discuss something with you.”<span class=\"pg\">p.141<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Post<\/span> Member and liaison for the Student Council under President Horikita Manabu.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Makes her series debut. Described as a strikingly beautiful girl with light-pink hair. Approaches Hoshinomiya Chie with calm, poised maturity.<span class=\"pg\">p.141–142<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Glances briefly at Ayanokōji in the hallway, then escorts Hoshinomiya back into the faculty office to attend to Student Council business.<span class=\"pg\">p.141–142<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Member / liaison for the Student Council under President Horikita Manabu.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Composed, responsible, trusted with student council affairs from her first month.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hoshinomiya Chie<\/b> Homeroom teacher and student council contact.<span class=\"pg\">p.141–142<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v1-p221-1\">→ After: Library intervention: the peacemaker of Class B<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v1-p221-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"sudou-ken hoshinomiya-chie ichinose-honami","q":"library intervention  the peacemaker of class b school library  lunchtime   okay  stop  stop   doesn t involve me  i m trying to use the library  so it does involve me  if you want to get violent  might i suggest that you do so outside   besides  don t you think you re provoking him  if things continue like this  i d have to report it to the school  do you want that   the threat that ends it   yamawaki backs down   s sorry  we don t want that  ichinose   if you re going to study here  please act like adults  thank you","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v1-p221-1\"><h3><span class=\"ttl\">Library intervention: the peacemaker of Class B<\/span><span class=\"meta\">Y1V1 · p.221–224<\/span><\/h3><p class=\"setup\">School library, lunchtime.<\/p><p class=\"with\">with <a href=\"sudou-ken.html\">Sudō Ken<\/a> · <a href=\"hoshinomiya-chie.html\">Hoshinomiya Chie<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Okay, stop. Stop!”<span class=\"pg\">p.222<\/span><\/li><li class=\"q spoken\">“Doesn’t involve me? I’m trying to use the library, so it does involve me. If you want to get violent, might I suggest that you do so outside?”<span class=\"pg\">p.222<\/span><\/li><li class=\"q spoken\">“Besides, don’t you think you’re provoking him? If things continue like this, I’d have to report it to the school. Do you want that?” (the threat that ends it — Yamawaki backs down: &quot;S-sorry. We don&#x27;t want that, Ichinose.&quot;)<span class=\"pg\">p.222<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Post<\/span> Called “the Class B student” who talks with Hoshinomiya-sensei.<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Shouts down Sudou mid-collar-grab on Yamawaki with a disinterested but logical argument, forcing Sudou to release him.<span class=\"pg\">p.221–222<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Delivers a parting standard before sweeping out, earning Ayanokōji&#x27;s open admiration.<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you’re going to study here, please act like adults. Thank you,”<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Identified by Ayanokōji as the Class B student previously seen talking with Hoshinomiya-sensei (p.141–142 debut).<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calm, gallant authority; defuses violence with pure logic and institutional stakes rather than status or aggression — noted as managing what Horikita&#x27;s bluntness inflames.<span class=\"pg\">p.222–224<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Releases his grip on her command alone.<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hoshinomiya Chie<\/b> Prior hallway association recalled from her debut.<span class=\"pg\">p.224<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v1-p141-1\">← Before: Debut: student council liaison<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p102-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"horikita-suzune ichinose-honami","q":"ch 4  4 4  she walks into the special building alone and offers class b s help her entrance is unannounced and physically striking to the narrator   we turned in response to the unexpected voice  a beautiful girl with strawberry blonde hair stood behind us  i recognized her  though i hadn t ever spoken to her before  she was a student from class b  ichinose  rumor had it she was a superb student   hey  you two  what are you doing   sorry to interrupt you like that  do you have a moment  oh  if you happen to be in the middle of a so so date  though  i d like you to break it up right away   ha ha  i see  this place is a little too hot to be a date spot  she has been watching class d without speaking to it   i ve met you twice before  we didn t talk directly  though  i remember seeing you in the library once  too   i have a very good memory  you know    ak s receipt of it as a backhanded comment on his own unremarkableness  her reason for being there is the case itself   i thought that surely there d be something here related to the brawl  i wasn t here yesterday when class b heard about the witness  later  i heard that class d was looking for evidence of sudou s innocence  and  hmm  a connection  well  i m not connected  when i heard about what happened  i had some doubts  so i thought i d come here myself to take a look  would you mind filling me in  she takes refusal as data  not as an insult   guess not  huh  well  if the other classes were interested  to horikita s accusati","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p102-1\"><h3><span class=\"ttl\">Ch.4 §4.4: she walks into the special building alone and offers Class B&#x27;s help<\/span><span class=\"meta\">Y1V2 · p.102–107<\/span><\/h3><p class=\"setup\">Her entrance is unannounced and physically striking to the narrator: &quot;We turned in response to the unexpected voice. A beautiful girl with strawberry-blonde hair stood behind us. I recognized her, though I hadn’t ever spoken to her before. She was a student from Class B, Ichinose. Rumor had it she was a superb student.&quot;<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hey, you two. What are you doing?”<span class=\"pg\">p.102<\/span><\/li><li class=\"q spoken\">“Sorry to interrupt you like that. Do you have a moment? Oh, if you happen to be in the middle of a so-so date, though, I’d like you to break it up right away.”<span class=\"pg\">p.102<\/span><\/li><li class=\"q spoken\">“Ha ha, I see. This place is a little too hot to be a date spot.”<span class=\"pg\">p.103<\/span><\/li><\/ul><details class=\"more\"><summary>19 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> She has been watching Class D without speaking to it: “I’ve met you twice before. We didn’t talk directly, though. I remember seeing you in the library once, too.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have a very good memory, you know.” — AK&#x27;s receipt of it as a backhanded comment on his own unremarkableness.<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> Her reason for being there is the case itself: “I thought that surely there’d be something here related to the brawl. I wasn’t here yesterday when Class B heard about the witness. Later, I heard that Class D was looking for evidence of Sudou’s innocence.” and “Hmm, a connection? Well, I’m not connected. When I heard about what happened, I had some doubts. So I thought I’d come here myself to take a look. Would you mind filling me in?”<span class=\"pg\">p.103–104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> She takes refusal as data, not as an insult: “Guess not, huh? Well, if the other classes were interested…”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> To Horikita&#x27;s accusation of an ulterior motive: “Ulterior motive? You think we’re working in the shadows to undermine both C and Class D?” — &quot;Ichinose wore a baffled expression. &#x27;Do you need to be that on guard? I’m really just curious, that’s all.&#x27;&quot;<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> Her first principle, aimed at Class D&#x27;s own logic: “So that’s what happened. This story hasn’t made its way to Class B yet. Hey, isn’t this a pretty big problem, though? It doesn’t really matter who lied since it’s an issue about violence, right? Shouldn’t you be hurrying to uncover the truth?”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> The question she asks instead of taking a side: “So you believe Sudou-kun because he’s your classmate. And your friend, of course, that much is obvious. So Class D is in an uproar because Sudou is being falsely charged, right?”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The answer she gets back, from one of the two Class D students — the text does not say which: “I’d report on it honestly. After all, covering for a lie would only come back to haunt us later.” — and her reaction is agreement, not argument; AK&#x27;s own line follows, &quot;Yeah, okay. I think so, too.&quot;<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> She does not take the dismissal personally: “Are you finished? You heard what you wanted.” is Horikita&#x27;s; her answer is “Hmm. Yeah, how about I help you out? To look for the witness, or whatever. You’re bound to get further with more people, right?”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> Her argument for intervening in another class&#x27;s discipline case, stated as system logic: “Are Classes D and B completely unrelated to each other? We don’t know when these cases will spring up, or whom they’ll involve. Since the classes are in constant competition, there’s always the chance that this will happen. This was the merely the first case. If the party that lied wins, that’d set a bad precedent. Also, I personally can’t turn away now that I know what happened.” (sic — &quot;the merely&quot;)<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> She prices her own value honestly, including the downside: “If Class B works with you, wouldn’t that dramatically improve your credibility? Though I suppose the opposite could be true, too. Class D may suffer greater consequences if the truth’s uncovered…” and “What do you think? I don’t believe it’s a bad suggestion.”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Position<\/span> She is taken on: Horikita says yes, gives her own name first, and AK records the result — &quot;We had unexpectedly made Ichinose of Class B’s acquaintance and accepted her as an ally. There was still the risk that this could lead to bad things. No matter what, things were going to change.&quot;<span class=\"pg\">p.106–107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> She knows Ayanokōji&#x27;s name the moment Horikita gives her own: “It’s nice to meet you, Horikita-san. And you too, Ayanokouji-kun.” — against AK&#x27;s assumption a minute earlier that &quot;she probably didn’t even know my name. I was only one of many students to her.&quot;<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> Her reading of Class D&#x27;s witness problem: “Well, that means there isn’t another witness. I mean, I guess someone from another class might have witnessed it, but it isn’t likely.”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> She is the source of the class-points half of the club rule, which Class D&#x27;s own teacher had never given them: “the school evaluates club and philanthropic activities, right? So if he enters a tournament and does well, Sudou-kun could earn points. Those’ll be tied to your class points, too. Wait… Did you guys not know that? Did your teacher not tell you?”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> Her diagnosis of the school&#x27;s teaching staff: “Your homeroom teacher is kind of weird.” / “She doesn’t seem motivated to tell us anything. She’s completely apathetic. Some teachers are like that.” / “Did you know that the school evaluates homeroom teachers when their class graduates?”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She arrives with nothing to gain, says so twice, is called a liar&#x27;s ally to her face, and still ends the afternoon as Class D&#x27;s first outside partner — the volume&#x27;s first Class B agent and the counter-example to Horikita&#x27;s theory that nobody helps for free.<span class=\"pg\">p.102–107<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Horikita suspects her on sight and hires her within the same conversation; the two are the pair who decide, over Sakura&#x27;s silence, to bring another class in.<span class=\"pg\">p.104–107<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> This is her first direct contact with Ayanokōji in the volume; every fact about her here comes from what she says in one afternoon, and no Class B student corroborates any of it.<span class=\"pg\">p.102–107<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p108-1\">→ After: Ch.4 §4.4–4.6: what Class B&#x27;s representative actually does<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p108-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka ichinose-honami","q":"ch 4  4 4 4 6  what class b s representative actually does her contact details are exchanged on her initiative   how about we exchange contact information  so things can progress smoothly    and ak learns her given name in the process   also  i learned that ichinose s first name was honami an unnecessary bit of information  a month after the entrance exam she is already her class s channel to the school s staff   thank you very much  it s been a pleasure    she has been at the dormitory manager s desk handling other students  complaints   some people from my class wanted to make requests about their dorms  i gathered everyone s thoughts on the matter and told the dorm manager  stuff like water usage  noise  and so on  her physical entrance in this section is written by ak as attraction  it is his narration  not her characterisation   she had beautiful long  wavy hair and big eyes  the second button of her blazer strained over her large chest  her upright posture matched her dignified personality  i found myself more attracted to her cool temperament than how cute she was  the reason her own teacher is different  given as a third party s motto   our homeroom teacher  hoshinomiya sensei  says it like it s her motto  she says she wants to do her best because the homeroom teacher for class a gets a special bonus  looks like it s pretty different for you guys   i think it would probably be good for us to meet up and discuss things    horikita s answer  which she takes without offe","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p108-1\"><h3><span class=\"ttl\">Ch.4 §4.4–4.6: what Class B&#x27;s representative actually does<\/span><span class=\"meta\">Y1V2 · p.108–115<\/span><\/h3><p class=\"setup\">Her contact details are exchanged on her initiative: “How about we exchange contact information, so things can progress smoothly?” — and AK learns her given name in the process: &quot;Also, I learned that Ichinose’s first name was Honami—an unnecessary bit of information.&quot; A month after the entrance exam she is already her class&#x27;s channel to the school&#x27;s staff: &quot;Thank you very much. It’s been a pleasure.&quot; — she has been at the dormitory manager&#x27;s desk handling other students&#x27; complaints: “Some people from my class wanted to make requests about their dorms. I gathered everyone’s thoughts on the matter and told the dorm manager. Stuff like water usage, noise, and so on.” Her physical entrance in this section is written by AK as attraction; it is his narration, not her characterisation: &quot;She had beautiful long, wavy hair and big eyes. The second button of her blazer strained over her large chest. Her upright posture matched her dignified personality. I found myself more attracted to her cool temperament than how cute she was.&quot;<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">The reason her own teacher is different, given as a third party&#x27;s motto: “Our homeroom teacher, Hoshinomiya-sensei, says it like it’s her motto. She says she wants to do her best because the homeroom teacher for Class A gets a…<span class=\"pg\">p.108<\/span><\/li><li class=\"q spoken\">“I think it would probably be good for us to meet up and discuss things.” — Horikita&#x27;s answer, which she takes without offence: “I never thought I’d receive aid from the enemy.”<span class=\"pg\">p.108<\/span><\/li><li class=\"q spoken\">“This seems like a problem we need to address before we can fight. We’re not really on equal footing, are we?” — the clearest statement in the volume of what the class-rank system does between classes.<span class=\"pg\">p.108<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> The reason her own teacher is different, given as a third party&#x27;s motto: “Our homeroom teacher, Hoshinomiya-sensei, says it like it’s her motto. She says she wants to do her best because the homeroom teacher for Class A gets a special bonus. Looks like it’s pretty different for you guys.”<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> She says the quiet part about Class D&#x27;s teacher out loud: “I’m envious of your relationship with your homeroom teacher. And your class environment.”<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Horikita, who has just insulted her, is charmed: &quot;Ha ha ha, that’s probably true. You’re pretty interesting.&quot;<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Her reliability is measurable: &quot;Every time she wanted permission to try something she’d contact us, even though she’d already said to leave things to her. I didn’t think she needed to limit herself so severely.&quot;<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Class B&#x27;s self-organisation is the fact this scene exists to reveal: “Class Rep? Why Class Rep?” — “I’m my class’s representative. It seems like that, anyway.” and “No, that’s just something Class B set up on its own. I think it’s good to have some assigned roles, right?”<span class=\"pg\">p.114–115<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The full informal officer set, in her own words: “Whether or not they serve a function is a different question, but we do have other roles for formality’s sake. Stuff like vice class representative, and secretary. They could be more useful when we have a cultural fair, or sports festival, or something. We could try deciding things on the spot, but that might lead to trouble.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> AK&#x27;s read of why she holds the role: “Most people wouldn’t want to be class representative. They’d be forced to do annoying stuff... However, with Ichinose taking the initiative for Class B, she probably didn’t foist things on others. I’d bet she handled her duties smoothly.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> She refuses the grandeur of it: “Do you think it’s weird? It’s all purely informal. Besides, there are quite a few troublemakers. We have to deal with a lot of stuff.” — AK&#x27;s note: &quot;As she said, &#x27;We have to deal with a lot of stuff,&#x27; Ichinose laughed.&quot;<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She is the first person outside Class D Horikita will negotiate with, and the negotiation is conducted entirely by Horikita&#x27;s hostility plus Horikita&#x27;s yes.<span class=\"pg\">p.108–110<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Two weeks in, she greets him first, knows his name, and walks to school with him — while he is still cataloguing her as an asset with unclear motive.<span class=\"pg\">p.114–115<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p102-1\">← Before: Ch.4 §4.4: she walks into the special building alone and offers Class B&#x27;s help<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p116-1\">→ After: Ch.4 §4.6: walking to school, and what she thinks the class system is hiding<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p116-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"ichinose-honami","q":"ch 4  4 6  walking to school  and what she thinks the class system is hiding   aren t you usually a little late  this reminds me that i ve never seen you around this time    his narration of the ask   ichinose s question sounded harmless  as if she were following some kind of template   i just stand out because i m the class rep  that s all    and his read of whether that is modesty   it didn t seem like she was trying to act modest  apparently that s what she truly thought   ah  that reminds me  did you hear about summer break  ayanokoujikun    printed without the hyphen in his name  kept as the translation has it   i ve heard rumors that we might be taking a vacation to a tropical island   i can t believe it  though  could we really go on a vacation   it s suspicious  after all  i think it s going to be a turning point     but i saw from her bitter smile that she also had doubts   yeah  yeah  i think there might be a hidden task  one that has a bigger impact on us than the midterms or final exams  otherwise  the difference between class a and us wouldn t close much  we could diminish the gap little by little  the only class point figures a student volunteers all volume   we have about 600 points  so our classes are around 350 points apart   so far  the midterm is all that s given us a chance to raise our class points  so losing at least a few points was unavoidable for us  i mean  even class a has lost points   i m concerned  but i think that there s a chance for us to make","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p116-1\"><h3><span class=\"ttl\">Ch.4 §4.6: walking to school, and what she thinks the class system is hiding<\/span><span class=\"meta\">Y1V2 · p.116–121<\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\">&quot;Aren’t you usually a little late? This reminds me that I’ve never seen you around this time.&quot; — his narration of the ask: &quot;Ichinose’s question sounded harmless, as if she were following some kind of template.&quot;<span class=\"pg\">p.116<\/span><\/li><li class=\"q spoken\">&quot;I just stand out because I’m the class rep. That’s all.&quot; — and his read of whether that is modesty: &quot;It didn’t seem like she was trying to act modest. Apparently that’s what she truly thought.&quot;<span class=\"pg\">p.116<\/span><\/li><li class=\"q spoken\">&quot;Ah, that reminds me. Did you hear about summer break, Ayanokoujikun?&quot; — printed without the hyphen in his name; kept as the translation has it.<span class=\"pg\">p.116<\/span><\/li><\/ul><details class=\"more\"><summary>21 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> The corridor&#x27;s reaction, in one line each: &quot;Ichinose, who was walking next to me, monopolized all of the girls’ attention.&quot;<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I’ve heard rumors that we might be taking a vacation to a tropical island.&quot;<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I can’t believe it, though. Could we really go on a vacation?&quot;<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It’s suspicious, after all. I think it’s going to be a turning point.&quot; — &quot;But I saw from her bitter smile that she also had doubts.&quot;<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yeah, yeah. I think there might be a hidden task, one that has a bigger impact on us than the midterms or final exams. Otherwise, the difference between Class A and us wouldn’t close much. We could diminish the gap little by little.&quot;<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> The only class-point figures a student volunteers all volume: &quot;We have about 600 points, so our classes are around 350 points apart.&quot;<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So far, the midterm is all that’s given us a chance to raise our class points, so losing at least a few points was unavoidable for us. I mean, even Class A has lost points.&quot;<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I’m concerned, but I think that there’s a chance for us to make a comeback. I intend to focus all of my emotional energy on making those preparations.&quot;<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We’re in a tight spot ourselves. If the gap widens any further, we won’t be able to catch up.&quot;<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But if we actually did vacation on a tropical island, that would be awesome!&quot;<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hey, I still have some things on my mind. May I ask you some questions?&quot;<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We’ve been separated into four classes from the start, right? Do you really think they separated us by ability?&quot;<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I’ve been thinking about it since we started here. Someone might be good at studying, but bad at physical activity. Another might be good at physical activities, but bad at studying. But if students are ranked by overall ability, doesn’t that mean that the lower classes are at an overwhelming disadvantage?&quot;<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If we were competing as individuals, sure. But this is a competition between classes, right? If you simply put all of the superior students into Class A, then doesn’t that mean the rest of us have virtually no chance of succeeding?&quot;<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;There’s definitely a big difference between classes A through D right now. However, I think they’re trying to hide something, but going about it in a weird way. Don’t you agree?&quot;<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ha, no reason, really. It’s just something that popped into my head. If it weren’t true, then it’d be fair to say the whole situation is cruel. I think that good students and good athletes were placed into Class D for a reason, as a countermeasure.&quot;<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I don’t think so. There’s a lot to be gained from an exchange of ideas. Also, since we’re cooperating now, there shouldn’t be any problems.&quot; — his gloss: &quot;She wasn’t complacent about being in Class B. That was just Ichinose’s natural personality.&quot;<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I don’t mind if I’m the one who does the talking and thinking. If you think it’s helpful information, then it’s okay for you to use it.&quot;<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Has a girl ever confessed her feelings to you?&quot; — the question she stops herself from explaining.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She works out the class-sorting problem in front of a stranger from the worst class in the school, offers her conclusion to him, and refuses to treat it as leverage: the only structural analysis of the four-class system a student gives all volume arrives unprompted and unguarded.<span class=\"pg\">p.119–120<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> She asks the question she cannot follow up on: &quot;Oh no, I’m sorry. It’s nothing.&quot; — and his note on it: &quot;It didn’t look like it was nothing.&quot;<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p108-1\">← Before: Ch.4 §4.4–4.6: what Class B&#x27;s representative actually does<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p121-1\">→ After: Ch.4 §4.7: she tries to dodge a confession and is made to give it<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p121-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami","q":"ch 4  4 7  she tries to dodge a confession and is made to give it she has already chosen the place and already knows what will happen there   i think someone will confess their feelings to me here  she said   huh  oh  yeah  kind of    that someone has confessed to her   well  if you re okay with it  can you spare a little time after class  i have some questions about confessions  i know all too well how busy you are with the incident right now  but   but you went to the scene of the crime the other day to investigate  right    class b is tracking class d s movements on the sudo case   i ll be waiting at the school entrance after class   ah  ayanokouji kun  over here  over here   i plan to finish this as soon as possible  follow me   love is kind of alien to me  i don t how to respond without hurting her feelings  i also don t know if we can stay good friends afterwards  i want you to help me    the missing word is the translation s  kept as printed   the person confessing her feelings to me is from class b   i d like for you to keep this secret  if not  things will probably get unpleasant  knowing you  ayanokouji kun  i doubt you ll go around telling people   huh  n no way  not at all  i ve never experienced this before     if she hadn t told me herself  i absolutely would not have believed it   so will you please pretend to be my boyfriend   i did a bit of research  and discovered that the rejected person hurts less if the object of their affection is already in a relationsh","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p121-1\"><h3><span class=\"ttl\">Ch.4 §4.7: she tries to dodge a confession and is made to give it<\/span><span class=\"meta\">Y1V2 · p.121–127<\/span><\/h3><p class=\"setup\">She has already chosen the place and already knows what will happen there: &quot;I think someone will confess their feelings to me here,&quot; she said.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Huh? Oh, yeah. Kind of.&quot; — that someone has confessed to her.<span class=\"pg\">p.121<\/span><\/li><li class=\"q spoken\">&quot;Well, if you’re okay with it, can you spare a little time after class? I have some questions about confessions. I know all too well how busy you are with the incident right now, but…&quot;<span class=\"pg\">p.121<\/span><\/li><li class=\"q spoken\">&quot;But you went to the scene of the crime the other day to investigate, right?&quot; — Class B is tracking Class D&#x27;s movements on the Sudō case.<span class=\"pg\">p.121<\/span><\/li><\/ul><details class=\"more\"><summary>25 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I’ll be waiting at the school entrance after class.&quot;<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> &quot;I was a little worried about finding Ichinose, but my anxieties quickly disappeared. She stood out even in this sea of students.&quot;<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> His attempt at a definition of her popularity: &quot;I could only describe it as an intoxicating, gentle power. A power that was amplified by how many of the first-year students recognized her. It was similar to Kushida, but even more so.&quot; and &quot;Ichinose was popular with boys and girls alike. They greeted her one after another.&quot;<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ah. Ayanokouji-kun. Over here, over here!&quot;<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I plan to finish this as soon as possible. Follow me.&quot;<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Love is kind of alien to me. I don’t how to respond without hurting her feelings. I also don’t know if we can stay good friends afterwards. I want you to help me.&quot; — the missing word is the translation&#x27;s, kept as printed.<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The person confessing her feelings to me…is from Class B.&quot;<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I’d like for you to keep this secret. If not, things will probably get unpleasant. Knowing you, Ayanokouji-kun, I doubt you’ll go around telling people.&quot;<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Huh?! N-no way. Not at all! I’ve never experienced this before.&quot; — &quot;If she hadn’t told me herself, I absolutely would not have believed it.&quot;<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So…will you please pretend to be my boyfriend?&quot;<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I did a bit of research, and discovered that the rejected person hurts less if the object of their affection is already in a relationship…&quot;<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I could say that you and I broke up, or that you left me or something.&quot;<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> The plan fails the moment it has to be spoken: &quot;Ichinose probably meant to say that yes, yes I was. But guilt over lying seemed to stopper her answer. The words got stuck in her throat.&quot;<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> His discovery of the weak point behind the office: &quot;I’d expected Ichinose to be a stalwart, reliable person, but apparently she had an unexpected weak point.&quot; and &quot;Ichinose, seeing Chihiro’s tears, grew flustered. Uncertain of what to do, she started panicking.&quot;<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;This is Ayanokouji-kun, from Class D. I’m sorry for bringing someone that you don’t know, Chihiro-chan.&quot;<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So, Ayanokouji-kun, he’s… Well, he’s my—&quot; — the sentence he cuts off.<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I was wrong. I didn’t respect Chihiro-chan’s feelings. I just wanted to avoid hurting her, and to run away. That was my mistake. Love is really tough, huh?&quot; — &quot;Ichinose muttered as she leaned against the handrail next to me.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I asked her if we could carry on like usual, but… I don’t know if we can go back to how things were.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yeah… Thanks for today. For coming along with me for such an odd request.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I guess our positions got reversed, huh? I planned on helping you, but then you ended up helping me.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;There’s no need for you to apologize, Ayanokouji-kun. None at all.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Now it’s my turn to help you. If there’s anything I can do, I will.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> She goes back and tells the truth anyway; the only account of the aftermath is his: &quot;I wondered how Class B’s Ichinose Honami planned to resolve this difficult situation.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> One morning walk, one aborted lie, one promise to help him in return — the volume&#x27;s only relationship that starts by asking him for something that is not information.<span class=\"pg\">p.116–127<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Chihiro is named only in this scene: a Class B girl who writes a love letter with a heart sticker and arranges to be confessed to in person behind the gymnasium. No surname, no other appearance in this volume.<span class=\"pg\">p.125–127<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p116-1\">← Before: Ch.4 §4.6: walking to school, and what she thinks the class system is hiding<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p152-1\">→ After: Ch.5 §5.0: a message board, a leaked past, and a screen<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p152-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"ichinose-honami","q":"ch 5  5 0  a message board  a leaked past  and a screen outside the shoe cubbies  she shows her phone  a message on the school homepage s board seeking witnesses  with a view count still in the dozens  she leans in to point at her screen while he explains the token key  the page records his reaction  not hers   have you ever checked out the school homepage  there s a message board  i requested that people come forward with information there  i said that if there anyone witnessed a violent incident at our school  i d like to hear about it   ah  regarding the stuff about points  don t worry  we just decided to do that on our own  besides  it will probably be difficult for us to get new information now  ah   it looks like i just got two messages regarding the post  there might be a little information   it looks like one of the boys from class c  ishizaki kun  was a bad seed in junior high  he was good at fighting  and terrorized the locals  a kid from his hometown probably leaked this   yeah  i think so too  i knew you d figure it out  kanzaki kun  great work  if we can verify this information  then we could be one step closer to proving sudou kun s innocence  but what we have is still pretty weak  isn t it   it ll be okay  besides  both class c and class a originally targeted us  anyway   anyway  we ll have to transfer points over to anyone who provides us with information  ah  but what if someone does so anonymously  in that case  how would we transfer over the points","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p152-1\"><h3><span class=\"ttl\">Ch.5 §5.0: a message board, a leaked past, and a screen<\/span><span class=\"meta\">Y1V2 · p.152–158<\/span><\/h3><p class=\"setup\">Outside the shoe cubbies, she shows her phone: a message on the school homepage&#x27;s board seeking witnesses, with a view count still in the dozens. She leans in to point at her screen while he explains the token key; the page records his reaction, not hers.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Have you ever checked out the school homepage? There’s a message board. I requested that people come forward with information there. I said that if there anyone witnessed a violent incident at our school, I’d like to hear about…<span class=\"pg\">p.153<\/span><\/li><li class=\"q spoken\">&quot;Ah, regarding the stuff about points, don’t worry. We just decided to do that on our own. Besides, it will probably be difficult for us to get new information now. Ah!&quot;<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\">&quot;It looks like I just got two messages regarding the post. There might be a little information.&quot;<span class=\"pg\">p.154<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Have you ever checked out the school homepage? There’s a message board. I requested that people come forward with information there. I said that if there anyone witnessed a violent incident at our school, I’d like to hear about it.&quot;<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It looks like one of the boys from Class C, Ishizaki-kun, was a bad seed in junior high. He was good at fighting, and terrorized the locals. A kid from his hometown probably leaked this.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yeah, I think so too. I knew you’d figure it out, Kanzaki-kun. Great work. If we can verify this information, then we could be one step closer to proving Sudou-kun’s innocence. But what we have is still pretty weak, isn’t it?&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It’ll be okay. Besides, both Class C and Class A originally targeted us, anyway.&quot;<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Anyway, we’ll have to transfer points over to anyone who provides us with information. Ah, but what if someone does so anonymously? In that case, how would we transfer over the points?&quot;<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> &quot;Ichinose and Kanzaki made it pretty clear that they wanted to be fair and square when competing against the school and the other students.&quot;<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> What he glimpses on her phone is left unnamed in this chapter; anything stronger would be a guess.<span class=\"pg\">p.158<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p121-1\">← Before: Ch.4 §4.7: she tries to dodge a confession and is made to give it<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p214-1\">→ After: Ch.6 §6.2: waiting at the entranceway<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p214-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami","q":"ch 6  6 2  waiting at the entranceway the entranceway after the hearing  ichinose and kanzaki have been waiting   on tenterhooks about the trial s results   yahoo  you re really late  huh   we were wondering what happened   i m sorry  was this a bad time   i see  so  you rejected the compromise  huh  class d is insisting on sudou s innocence until the very end   but like ayanokouji kun says  sudou s suspension would be a loss for class d  if sudou were suspended due to his bad behavior  then his chances of being a team regular would probably vanish  he d be back to square one   if you think so  shouldn t you have stopped it   if you re brought back into a retrial  you ll inevitably lose  just like kanzaki says  obtaining a not guilty verdict is virtually impossible   are you still going to fight  even without new evidence or testimony   hmm  well  i don t think we ll be able to obtain any more leads  but i ll go check what information i can gather from the internet","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p214-1\"><h3><span class=\"ttl\">Ch.6 §6.2: waiting at the entranceway<\/span><span class=\"meta\">Y1V2 · p.214–215<\/span><\/h3><p class=\"setup\">The entranceway after the hearing; Ichinose and Kanzaki have been waiting, &quot;on tenterhooks about the trial’s results.&quot;<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Yahoo! You’re really late, huh?&quot;<span class=\"pg\">p.214<\/span><\/li><li class=\"q spoken\">&quot;We were wondering what happened.&quot;<span class=\"pg\">p.214<\/span><\/li><li class=\"q spoken\">&quot;I’m sorry. Was this a bad time?&quot;<span class=\"pg\">p.214<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The apology lands on the exact sentence Sakura was about to finish; the narrator lets the moment go rather than reopen it.<span class=\"pg\">p.214<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I see. So, you rejected the compromise, huh? Class D is insisting on Sudou’s innocence until the very end?&quot;<span class=\"pg\">p.214<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But like Ayanokouji-kun says, Sudou’s suspension would be a loss for Class D. If Sudou were suspended due to his bad behavior, then his chances of being a team regular would probably vanish. He’d be back to square one.&quot;<span class=\"pg\">p.214<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If you think so, shouldn’t you have stopped it?&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If you’re brought back into a retrial, you’ll inevitably lose. Just like Kanzaki says, obtaining a not-guilty verdict is virtually impossible.&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Are you still going to fight? Even without new evidence or testimony?&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She argues the case is unwinnable and then offers to work it anyway — the contradiction the chapter lets stand.<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hmm. Well, I don’t think we’ll be able to obtain any more leads, but I’ll go check what information I can gather from the Internet.&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She laughs while offering help &quot;though it wouldn’t have been odd for her to wash her hands off us at this point.&quot;<span class=\"pg\">p.215<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p152-1\">← Before: Ch.5 §5.0: a message board, a leaked past, and a screen<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p216-1\">→ After: Ch.6 §6.2: the request, and the price<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p216-1","v":"y1v2","y":1,"o":2,"k":"action spoken","w":"horikita-suzune ichinose-honami","q":"ch 6  6 2  the request  and the price   not necessary  what do you mean  horikita san   preparing something   oh  that s going to be a really hard request   ah  no  well  this should be within the range of what we can do  i think  that s because i plan to figure out what s happening to class d  i ve got tons and tons of things i want to know  but  well  maybe it would be better for you not to tell us why   when did you come up with this   that an incredible move  i went to the scene of the crime and even i didn t think of that  or  i guess i should say  i was completely in the dark about it  it wasn t even close to what i could imagine   an unusual idea  you can probably anticipate the results  too  but does such a thing even exist   ha ha  yeah  you might be right  it s a change for me  but it s certainly one way of doing things   well  since a lie started all this trouble  maybe it ll take another lie to close the books on this incident  that s what i think  anyway   hey  kanzaki kun  did you help us so that we would outpace class c   but i was just thinking  perhaps what we re doing right now might end up coming back to bite you in the ass later   man  i completely neglected to calculate the fact that class d has a girl like you   i ll lend this to you  please return it later","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p216-1\"><h3><span class=\"ttl\">Ch.6 §6.2: the request, and the price<\/span><span class=\"meta\">Y1V2 · p.216–218<\/span><\/h3><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Not necessary? What do you mean, Horikita-san?&quot;<span class=\"pg\">p.216<\/span><\/li><li class=\"q spoken\">&quot;Preparing something?&quot;<span class=\"pg\">p.216<\/span><\/li><li class=\"q spoken\">&quot;Oh… That’s going to be a really hard request.&quot;<span class=\"pg\">p.216<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Ah, no. Well, this should be within the range of what we can do, I think. That’s because I plan to figure out what’s happening to Class D. I’ve got tons and tons of things I want to know, but… Well, maybe it would be better for you not to tell us why?&quot;<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;When did you come up with this?&quot;<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That…an incredible move. I went to the scene of the crime and even I didn’t think of that. Or, I guess I should say, I was completely in the dark about it. It wasn’t even close to what I could imagine.&quot;<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;An unusual idea. You can probably anticipate the results, too. But does such a thing even exist?&quot;<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ha ha, yeah. You might be right. It’s a change for me. But…it’s certainly one way of doing things.&quot;<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Well, since a lie started all this trouble, maybe it’ll take another lie to close the books on this incident. That’s what I think, anyway.&quot;<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The reply that follows — &quot;Mmmhmm, I see. An eye for an eye, a lie for a lie, yeah? But is that even possible, I wonder? I can’t imagine such a thing would be easy to obtain.&quot; — is untagged; it is not assigned to her here.<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hey, Kanzaki-kun. Did you help us so that we would outpace Class C?&quot;<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But I was just thinking, perhaps what we’re doing right now might end up coming back to bite you in the ass later?&quot;<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Man. I completely neglected to calculate the fact that Class D has a girl like you.&quot;<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> She takes out her phone and hands it over.<span class=\"pg\">p.217–218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I’ll lend this to you. Please return it later.&quot;<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her cooperation is explicitly costly to her principles: the plan depends on a lie, and &quot;For someone like Ichinose, who hated lying, it was a harsh request.&quot;<span class=\"pg\">p.216–217<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> The compliment is professional and ungrudging — she names Horikita as a factor Class D has that she failed to price in.<span class=\"pg\">p.216–218<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Kanzaki warns her the favor may be turned against Class B later, and she accepts that risk without extracting a condition.<span class=\"pg\">p.217<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p214-1\">← Before: Ch.6 §6.2: waiting at the entranceway<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p226-1\">→ After: Ch.7 §7.2: she steps into the corridor<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p226-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"ichinose-honami","q":"ch 7  7 2  she steps into the corridor as the three turn to leave  one other person stands in their way   the page introduces her as  who d been waiting for all of the players in this drama to appear    and she puts herself between class c and the exit   i think you guys might want to consider that idea  actually   what do you mean  what if i said that i m here because i m involved in this case   ha ha  well  i guess i m well known among the members of class c   you re certainly right that class b has nothing to do with this  but how do you feel about involving so many people in your lies   so evildoers remain obstinate until the very end  it s about time for you to pay the piper   you lied  we can all see through you  you got violent in the end  if you don t want that fact to become public knowledge  withdraw your claim right away   didn t you think that the school s response to this incident was rather strange   when you raised the issue with the school  why wasn t sudou punished immediately  why give an opportunity to escape by granting a grace period of several days  what do you think was the reason   is that really okay  though  if you leave this place  you might regret it for the rest of your life   don t you understand  the school knows that you re lying  class c  they ve known from the beginning   ha ha ha ha  you guys are so funny   you ve been dancing to my tune all this time   i have actual evidence","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p226-1\"><h3><span class=\"ttl\">Ch.7 §7.2: she steps into the corridor<\/span><span class=\"meta\">Y1V2 · p.226–228<\/span><\/h3><p class=\"setup\">As the three turn to leave, one other person stands in their way — the page introduces her as &quot;who’d been waiting for all of the players in this drama to appear&quot; — and she puts herself between Class C and the exit.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I think you guys might want to consider that idea, actually.&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q spoken\">&quot;What do you mean? What if I said that I’m here because I’m involved in this case?&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q spoken\">&quot;Ha ha. Well, I guess I’m well known among the members of Class C.&quot;<span class=\"pg\">p.226<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You’re certainly right that Class B has nothing to do with this. But how do you feel about involving so many people in your lies?&quot;<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So evildoers remain obstinate until the very end. It’s about time for you to pay the piper!&quot;<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You lied. We can all see through you. You got violent in the end. If you don’t want that fact to become public knowledge, withdraw your claim right away.&quot;<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She &quot;grinned and talked with greater animation, as if relishing this,&quot; walking toward them like a detective revealing the culprit.<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Didn’t you think that the school’s response to this incident was rather strange?&quot;<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;When you raised the issue with the school, why wasn’t Sudou punished immediately? Why give an opportunity to escape by granting a grace period of several days? What do you think was the reason?&quot;<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Is that really okay, though? If you leave this place, you might regret it for the rest of your life.&quot;<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Don’t you understand? The school knows that you’re lying, Class C. They’ve known from the beginning.&quot;<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ha ha ha ha. You guys are so funny.&quot;<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You’ve been dancing to my tune all this time.&quot;<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I have actual evidence,&quot;<span class=\"pg\">p.228<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p216-1\">← Before: Ch.6 §6.2: the request, and the price<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p228-1\">→ After: Ch.7 §7.2: the security-camera argument<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p228-1","v":"y1v2","y":1,"o":2,"k":"action spoken","w":"ichinose-honami","q":"ch 7  7 2  the security camera argument   did you know that there are security cameras installed everywhere around the school  it s a measure they ve taken in order to monitor what we do every day   that s too bad  isn t it  if you want to set a trap for someone  you d need to do it in a place without any cameras   you re right that  by and large  cameras aren t installed in most of this building s hallways  however  there are exceptions  and several places in which security cameras have been installed  like in front of the faculty room and the science lab  obviously  there are many valuables stored in the faculty room  you know  additionally  the science lab has many chemical products  since the science lab is on this level  it s only natural that a camera would be installed here   have you looked back there  behind you  there s one there too  right   so if we d installed a camera  like you said  would we have prepared one on that side  too  besides  how exactly would we have prepared surveillance cameras when we can t even leave campus in the first place   this is the third floor  but did you really check  maybe you only looked at the second or the fourth  perhaps the cameras were truly set up here as a trap   also  you realize that you just destroyed yourselves  right  normal people wouldn t think to check whether there were security cameras  right  that s basically admitting your guilt   the security cameras couldn t record the sounds of your voices  but they definitely c","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p228-1\"><h3><span class=\"ttl\">Ch.7 §7.2: the security-camera argument<\/span><span class=\"meta\">Y1V2 · p.228–231<\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\">&quot;Did you know that there are security cameras installed everywhere around the school? It’s a measure they’ve taken in order to monitor what we do every day.&quot;<span class=\"pg\">p.228–229<\/span><\/li><li class=\"q spoken\">&quot;That’s too bad, isn’t it? If you want to set a trap for someone, you’d need to do it in a place without any cameras.&quot;<span class=\"pg\">p.229<\/span><\/li><li class=\"q spoken\">&quot;You’re right that, by and large, cameras aren’t installed in most of this building’s hallways. However, there are exceptions, and several places in which security cameras have been installed, like in front of the faculty room…<span class=\"pg\">p.229<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You’re right that, by and large, cameras aren’t installed in most of this building’s hallways. However, there are exceptions, and several places in which security cameras have been installed, like in front of the faculty room and the science lab. Obviously, there are many valuables stored in the faculty room, you know? Additionally, the science lab has many chemical products. Since the science lab is on this level, it’s only natural that a camera would be installed here.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Have you looked back there, behind you? There’s one there too, right?&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So if we’d installed a camera, like you said, would we have prepared one on that side, too? Besides, how exactly would we have prepared surveillance cameras when we can’t even leave campus in the first place?&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;This is the third floor, but did you really check? Maybe you only looked at the second or the fourth? Perhaps the cameras were truly set up here as a trap?&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Also, you realize that you just destroyed yourselves, right? Normal people wouldn’t think to check whether there were security cameras, right? That’s basically admitting your guilt.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The security cameras couldn’t record the sounds of your voices, but they definitely captured the decisive moment you threw the first punch.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> She passes the baton to Ayanokōji for the student-council half of the bluff.<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Innocence? That depends on what you’re innocent of. We know that both parties took damage during the incident. No matter the circumstances, Sudou hit the three of you. That’s undeniable. Of course, if the security footage can prove that Sudou wasn’t the one who called you three over here, he’d probably receive the lightest possible punishment. However, his position as a regular would still be threatened. He might not be allowed to participate in tournaments.&quot;<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If someone checked the security camera footage, it would expose your lies. If that were to happen, chances are good you’d be expelled. Anyone could see that.&quot;<span class=\"pg\">p.231<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p226-1\">← Before: Ch.7 §7.2: she steps into the corridor<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p232-1\">→ After: Ch.7 §7.2–7.3: the only way out, and the cameras that were never the school’s<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p232-1","v":"y1v2","y":1,"o":2,"k":"action spoken","w":"ichinose-honami","q":"ch 7  7 2 7 3  the only way out  and the cameras that were never the school s   it s rather early to draw a conclusion  we ll give you one last chance  there s only one way to save both class c and class d   there s only one way to resolve this issue  tell the school that you wish to withdraw your complaint  if you do that  the school will not bring forward the security camera footage  if there s no complaint  no one can be punished  additionally  if the security footage is never brought up  class d benefits  too  as we already know  if the security footage were brought produced  sudou would still face some degree of punishment  in other words  class c and class d can come to a compromise together  the school can t investigate if they can t watch the video and see that you lied  right   well  you re not being very cooperative  therefore  we have no choice but to prepare  we ll have the school confirm the security footage right away  and you ll be expelled   whew  i feel so much better  thanks so much  thanks for giving me such a huge role  i was so happy   ha ha ha  yeah  i guess so  but the case is closed  eh   when the day comes  you guys will probably become formidable rivals for class c  ayanokouji kun   if horikita san were in class b  we might have gotten to class a right away   i ll definitely return the points i borrowed  just tell me when you want them   huh  w wait a minute   oh  yeah  that reminds me  there was one thing i wanted to tell you  ayanokouji kun","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p232-1\"><h3><span class=\"ttl\">Ch.7 §7.2–7.3: the only way out, and the cameras that were never the school’s<\/span><span class=\"meta\">Y1V2 · p.232–235<\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\">&quot;It’s rather early to draw a conclusion. We’ll give you one last chance. There’s only one way to save both Class C and Class D.&quot;<span class=\"pg\">p.232<\/span><\/li><li class=\"q spoken\">&quot;There’s only one way to resolve this issue. Tell the school that you wish to withdraw your complaint. If you do that, the school will not bring forward the security camera footage. If there’s no complaint, no one can be…<span class=\"pg\">p.232<\/span><\/li><li class=\"q spoken\">&quot;Well, you’re not being very cooperative. Therefore, we have no choice but to prepare. We’ll have the school confirm the security footage right away, and you’ll be expelled.&quot;<span class=\"pg\">p.232<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;There’s only one way to resolve this issue. Tell the school that you wish to withdraw your complaint. If you do that, the school will not bring forward the security camera footage. If there’s no complaint, no one can be punished. Additionally, if the security footage is never brought up, Class D benefits, too. As we already know, if the security footage were brought produced, Sudou would still face some degree of punishment. In other words, Class C and Class D can come to a compromise together. The school can’t investigate if they can’t watch the video and see that you lied, right?&quot;<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> She refuses to let Ishizaki call anyone and gives him no time to think.<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> She walks the three Class C students to the student council room, sandwiched between her and Ayanokōji.<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Whew! I feel so much better! Thanks so much! Thanks for giving me such a huge role! I was so happy!&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ha ha ha, yeah. I guess so. But the case is closed, eh?&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> She and Kanzaki bought the cameras, and with the Professor installed them during the lunch break.<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;When the day comes, you guys will probably become formidable rivals for Class C, Ayanokouji-kun.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If Horikita-san were in Class B, we might have gotten to Class A right away.&quot;<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I’ll definitely return the points I borrowed. Just tell me when you want them.&quot;<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Huh?! W-wait a minute!&quot;<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Oh, yeah, that reminds me. There was one thing I wanted to tell you, Ayanokouji-kun.&quot;<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> What she wanted to tell him is cut off by his sprint; it comes out later as the warning about Ryuuen.<span class=\"pg\">p.235<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p228-1\">← Before: Ch.7 §7.2: the security-camera argument<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p236-1\">→ After: Ch.7 §7.4: the act at the shutter, and the warning about Ryuuen<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y1v2-p236-1","v":"y1v2","y":1,"o":2,"k":"action spoken","w":"horikita-suzune ichinose-honami","q":"ch 7  7 4  the act at the shutter  and the warning about ryuuen   huh  idol  that s amazing  she s an entertainer  ooh  shake my hand  shake my hand   even so  that s so amazing  i ve never thought about becoming an idol or anything   whoa  you re so amazingly cute  you make a completely different impression without your glasses    after looking shizuku up on her phone  ah  i ll help out too   i m ichinose  from class b  it s nice to meet you  sakura san   i probably shouldn t be saying this right now  but there was someone pulling the strings behind this whole sudou incident   to tell the truth  there was a dispute between class b and class c students before  that time  though  the school didn t get involved  someone named ryuuen kun masterminded that one   that s because he hasn t seen any reason to reveal himself just yet  there s no reason that you d know him   i m the most vigilant of all the first years here  i think he set up sudou kun to look like a liar  and instigated the dispute with class b  this was all his handiwork  he doesn t hesitate to hurt other people for the sake of his own interests  he s a formidable opponent   somehow  yeah  however  if you looked at it like a game  i can t say whether i won or lost  anyway  i think because what he devised was easier to see through this time  i ve started to understand how this school is structured  you should be careful   so if anything ever happens  you can come to me for help  talk to me whenever you need it","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v2-p236-1\"><h3><span class=\"ttl\">Ch.7 §7.4: the act at the shutter, and the warning about Ryuuen<\/span><span class=\"meta\">Y1V2 · p.236–241<\/span><\/h3><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Huh?! Idol?! That’s amazing! She’s an entertainer! Ooh, shake my hand, shake my hand!&quot;<span class=\"pg\">p.239<\/span><\/li><li class=\"q spoken\">&quot;Even so, that’s so amazing! I’ve never thought about becoming an idol or anything.&quot;<span class=\"pg\">p.239<\/span><\/li><li class=\"q spoken\">&quot;Whoa… You’re so amazingly cute! You make a completely different impression without your glasses!&quot; — after looking Shizuku up on her phone<span class=\"pg\">p.240<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> She sticks close when Ayanokōji runs to the electronics store and goes quiet on his signal.<span class=\"pg\">p.236<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Matching the delinquent act, &quot;her tone was cruel&quot;; she pinches the letters up by their corners with finger and thumb.<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ah, I’ll help out too.&quot;<span class=\"pg\">p.240<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I’m Ichinose, from Class B. It’s nice to meet you, Sakura-san.&quot;<span class=\"pg\">p.240<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I probably shouldn’t be saying this right now, but…there was someone pulling the strings behind this whole Sudou incident.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;To tell the truth, there was a dispute between Class B and Class C students before. That time, though, the school didn’t get involved. Someone named Ryuuen-kun masterminded that one.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> &quot;Ichinose, who always looked so bright, now appeared somber and grim.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That’s because he hasn’t seen any reason to reveal himself just yet. There’s no reason that you’d know him.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I’m the most vigilant of all the first-years here. I think he set up Sudou-kun to look like a liar, and instigated the dispute with Class B. This was all his handiwork. He doesn’t hesitate to hurt other people for the sake of his own interests. He’s a formidable opponent.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Somehow, yeah. However, if you looked at it like a game, I can’t say whether I won or lost… Anyway, I think because what he devised was easier to see through this time, I’ve started to understand how this school is structured. You should be careful.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So if anything ever happens, you can come to me for help. Talk to me whenever you need it.&quot;<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She names the road not taken: if Horikita had been in Class B, Class B might already have reached Class A.<span class=\"pg\">p.235<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y1v2-p232-1\">← Before: Ch.7 §7.2–7.3: the only way out, and the cameras that were never the school’s<\/button><\/div><\/article>"}];
